{
  "cvars": {
    "ivs": [
      {
        "description": "Instructor physical appearance (average beauty rating across 6 judges), standardized (z-score). Hypothesized to positively influence student evaluations.",
        "columns": [
          "beauty_z"
        ]
      }
    ],
    "dv": {
      "description": "Course overall teaching evaluation score (student instructional rating) on a 1-5 scale.",
      "columns": [
        "eval"
      ]
    },
    "controls": [
      {
        "description": "Instructor age in years (continuous). Controls for experience/age effects on evaluations.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Instructor gender (categorical: 'male' or 'female'). Controls for gender differences in ratings.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "gender"
        ]
      },
      {
        "description": "Whether the instructor is a minority (categorical: 'yes'/'no'). Controls for demographic effects on ratings.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "minority"
        ]
      },
      {
        "description": "Tenure status (categorical: 'yes'/'no'). Controls for job status effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "tenure"
        ]
      },
      {
        "description": "Native English speaker status (categorical: 'yes'/'no'). Controls for language effects on evaluations.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "native"
        ]
      },
      {
        "description": "Course division (categorical: 'lower'/'upper'). Controls for course level differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "division"
        ]
      },
      {
        "description": "Course credits indicator (categorical: 'single' [single-credit elective] vs 'more'). Controls for course type.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "credits"
        ]
      },
      {
        "description": "Log of the number of students who participated in the evaluation (log-transformed class size). Controls for class-size effects and stabilizes skew.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "students_log"
        ]
      },
      {
        "description": "Professor identifier. Used as grouping variable for a random intercept to account for multiple course observations per instructor.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "prof"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Prepares the dataset for modeling. Key steps:\n    - Keep only rows with non-missing values for variables used in the model.\n    - Coerce categorical columns to pandas.Categorical dtype.\n    - Standardize the beauty variable to a z-score (beauty_z).\n    - Create a log transform of students (students_log).\n    - Return a dataframe containing only the columns used in the statistical model.\n    \"\"\"\n    df = df.copy()\n\n    # Required raw columns\n    required_cols = ['beauty', 'eval', 'age', 'gender', 'minority', 'tenure', 'native', 'division', 'credits', 'students', 'prof']\n\n    # Drop rows with missing values in required columns\n    df = df.dropna(subset=required_cols)\n\n    # Ensure correct dtypes for categorical variables\n    for c in ['gender', 'minority', 'tenure', 'native', 'division', 'credits', 'prof']:\n        # If any of these are numeric codes, treat them as strings first\n        df[c] = df[c].astype('category')\n\n    # Standardize the beauty rating (z-score). Use population std (ddof=0) for interpretability.\n    df['beauty_z'] = (df['beauty'] - df['beauty'].mean()) / (df['beauty'].std(ddof=0) if df['beauty'].std(ddof=0) != 0 else 1.0)\n\n    # Log-transform the number of students who participated to reduce skew\n    # Add a small constant guard in case of zeros (shouldn't occur given schema min=5)\n    df['students_log'] = np.log(df['students'].astype(float) + 1e-6)\n\n    # Keep only the columns needed for modeling\n    out_cols = ['beauty_z', 'eval', 'age', 'gender', 'minority', 'tenure', 'native', 'division', 'credits', 'students_log', 'prof']\n    df = df[out_cols].reset_index(drop=True)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> dict:\n    \"\"\"\n    Fits two complementary models to estimate the association between instructor beauty and student evaluations:\n    1) Mixed-effects linear model with a random intercept for professor (accounts for multiple courses per instructor).\n    2) OLS with standard errors clustered by professor (robustness check).\n\n    Returns a dictionary with the fitted model results objects.\n    \"\"\"\n    import statsmodels.formula.api as smf\n    import statsmodels.api as sm\n\n    # Ensure incoming df contains required columns\n    required = ['beauty_z', 'eval', 'age', 'gender', 'minority', 'tenure', 'native', 'division', 'credits', 'students_log', 'prof']\n    missing = [c for c in required if c not in df.columns]\n    if len(missing) > 0:\n        raise ValueError(f\"Transformed dataframe is missing required columns: {missing}\")\n\n    # Formula: main effect of beauty plus controls; categorical controls are wrapped with C(...)\n    formula = (\n        \"eval ~ beauty_z + age + C(gender) + C(minority) + C(tenure) + C(native) + \"\n        \"C(division) + C(credits) + students_log\"\n    )\n\n    results = {}\n\n    # 1) Mixed effects model with random intercept for professor\n    try:\n        md = smf.mixedlm(formula, df, groups=df['prof'])\n        mdf = md.fit(reml=False)\n        results['mixedlm'] = mdf\n    except Exception as e:\n        results['mixedlm_error'] = str(e)\n\n    # 2) OLS with clustered standard errors by professor (robustness)\n    try:\n        ols = smf.ols(formula, df).fit()\n        # clustered SEs by 'prof'\n        ols_cluster = ols.get_robustcov_results(cov_type='cluster', groups=df['prof'])\n        results['ols_clustered'] = ols_cluster\n    except Exception as e:\n        results['ols_error'] = str(e)\n\n    return results\n"
}

{
  "cvars": {
    "ivs": [
      {
        "description": "Instructor physical attractiveness rating (panel average), mean-centered. Primary independent variable capturing perceived instructor beauty.",
        "columns": [
