      {
        "description": "Instructor gender coded as female = 1, male = 0. Used as a control and also tested as a moderator of the beauty effect.",
        "is_moderator": true,
        "moderator_on": "Instructor beauty",
        "columns": [
          "female"
        ]
      },
      {
        "description": "Instructor age in years (numeric). Control for experience/age-related effects on evaluations.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "age"
        ]
      },
      {
        "description": "Instructor minority status coded yes = 1, no = 0. Controls for effects of minority status on evaluations.",
