        "moderator_on": "",
        "columns": [
          "native_yes"
        ]
      },
      {
        "description": "Instructor tenure status coded yes = 1, no = 0. Controls for job security / seniority effects.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "tenure_yes"
        ]
      },
      {
        "description": "Log of number of students who participated in the evaluation (log-transformed class size). Controls for class-size effects on mean evaluation scores.",
        "is_moderator": false,
